import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Kimi Code 教程","description":"从官方安装脚本装上 Kimi Code CLI，完成 /login，跑完第一次对话；再决定 VS Code 扩展、ACP 或第三方 API。旧版 Python kimi-cli 只在附录迁移。","frontmatter":{"title":"Kimi Code 教程","description":"从官方安装脚本装上 Kimi Code CLI，完成 /login，跑完第一次对话；再决定 VS Code 扩展、ACP 或第三方 API。旧版 Python kimi-cli 只在附录迁移。","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/kimi-code/kimi-code.md","filePath":"zh/products/kimi-code/kimi-code.md","lastUpdated":1787110548000}'),a={name:"zh/products/kimi-code/kimi-code.md"};function s(r,t,n,l,c,h){return o(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="kimi-code-教程" tabindex="-1">Kimi Code 教程 <a class="header-anchor" href="#kimi-code-教程" aria-label="Permalink to &quot;Kimi Code 教程&quot;">​</a></h1><blockquote><p>本页带你把 <strong>Kimi Code</strong> 装上并能改代码。命令与包名抄自 <a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">产品文档 · 开始使用</a> 和 <a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">MoonshotAI/kimi-code README</a>。参数全集见 <a href="./kimi-code-cheatsheet.html">速查表</a>。家族边界见 <a href="./">学习地图</a>。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>目标</strong></p><ul><li>用官方脚本或 npm 装上可执行文件 <code>kimi</code></li><li>用 <code>/login</code> 接到 Kimi Code 会员或开放平台 Key</li><li>完成一次只读摸底和一次带确认的小改动</li><li>知道 VS Code 扩展、<code>kimi acp</code>、第三方 API 各自怎么进</li></ul><p><strong>非目标</strong></p><ul><li>不写 Kimi 对话 / Work / Claw 教程</li><li>不把旧版 Python <code>kimi-cli</code> 当主安装路径</li><li>不编套餐价格、不编「应该能装上 VS Code 扩展」</li></ul><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><p>官方 <a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">开始使用</a> 与 <a href="https://www.kimi.ai/zh-hans/help/kimi-code/cli-getting-started" target="_blank" rel="noreferrer">帮助中心</a>：</p><ul><li>操作系统：macOS、Linux，或 Windows（PowerShell）</li><li>账号：有效的 <strong>Kimi 会员订阅</strong>，或可调用的 API Key</li><li>TUI 推荐真彩色 + 连字终端（官方举例 Kitty、Ghostty）</li><li>Windows：<strong>先装 <a href="https://gitforwindows.org/" target="_blank" rel="noreferrer">Git for Windows</a></strong>。CLI 用其中的 Git Bash 当 Shell；若 Git Bash 不在默认路径，把 <code>KIMI_SHELL_PATH</code> 设成 <code>bash.exe</code> 的绝对路径</li><li>npm 通道额外要求：<strong>Node.js 22.19.0 或更高</strong></li></ul><h2 id="_1-安装-cli" tabindex="-1">1. 安装 CLI <a class="header-anchor" href="#_1-安装-cli" aria-label="Permalink to &quot;1. 安装 CLI&quot;">​</a></h2><p>官方提供两种方式。<strong>推荐安装脚本</strong>（无需预装 Node.js）。</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-9Cb8T" id="tab-TygJyOD" checked><label data-title="macOS / Linux" for="tab-TygJyOD">macOS / Linux</label><input type="radio" name="group-9Cb8T" id="tab-jzQEhtx"><label data-title="Windows PowerShell" for="tab-jzQEhtx">Windows PowerShell</label><input type="radio" name="group-9Cb8T" id="tab-gWv2St_"><label data-title="npm" for="tab-gWv2St_">npm</label><input type="radio" name="group-9Cb8T" id="tab-OUu6he0"><label data-title="pnpm" for="tab-OUu6he0">pnpm</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://code.kimi.com/kimi-code/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">code.kimi.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kimi</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code</span></span></code></pre></div></div></div><p>来源：<a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">开始使用</a>、<a href="https://github.com/MoonshotAI/kimi-code" target="_blank" rel="noreferrer">仓库 README</a>。脚本会下载最新版、校验 checksum，并把 <code>kimi</code> 放进 <code>PATH</code>。</p><p>验证：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>找不到命令：重开终端，或 <code>source ~/.bashrc</code> / <code>source ~/.zshrc</code>。帮助中心补充：再查 <code>~/.local/bin</code> 是否在 <code>PATH</code> 里。</p><p>macOS 首次启动可能被 Gatekeeper 拖慢。帮助中心原文：把终端 App 加到 <strong>系统设置 → 隐私与安全性 → 开发者工具</strong>。</p><p><strong>升级</strong>：<code>kimi upgrade</code>（别名 <code>kimi update</code>），选 <code>Install update now</code>；或 <code>npm install -g @moonshot-ai/kimi-code@latest</code>。What&#39;s New 还写过 Homebrew 用户用 <code>brew upgrade kimi-code</code>。Getting Started <strong>没有</strong> <code>brew install</code> 原文，本页不补。</p><p><strong>卸载</strong>：脚本安装则删除 <code>kimi</code> 可执行文件；npm 则 <code>npm uninstall -g @moonshot-ai/kimi-code</code>。</p><blockquote><p><strong>不要抄旧脚本。</strong> 帮助中心个别旧页仍写 <code>curl -LsSf https://code.kimi.com/install.sh | bash</code> 或 <code>uv tool install --python 3.13 kimi-cli</code>。那是 Python <code>kimi-cli</code>。现行官方路径带 <code>/kimi-code/</code>，包名是 <code>@moonshot-ai/kimi-code</code>。</p></blockquote><h2 id="_2-登录" tabindex="-1">2. 登录 <a class="header-anchor" href="#_2-登录" aria-label="Permalink to &quot;2. 登录&quot;">​</a></h2><p>进入项目目录启动 TUI：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> your-project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span></span></code></pre></div><p>第一次在输入框执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/login</span></span></code></pre></div><p>平台选择器支持两种方式（<a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/getting-started" target="_blank" rel="noreferrer">开始使用</a>）：</p><table tabindex="0"><thead><tr><th>选项</th><th>官方说明</th></tr></thead><tbody><tr><td><strong>Kimi Code（OAuth）</strong></td><td>验证码流程：任意设备打开链接、登录、输入验证码</td></tr><tr><td><strong>Kimi Platform API 密钥</strong></td><td>填 <code>platform.kimi.com</code> 或 <code>platform.kimi.ai</code> 的 Key</td></tr></tbody></table><p>无 TUI 时可用非交互：<code>kimi login</code>（RFC 8628 device-code，验证地址和用户码打到 stderr）。</p><p>退出：<code>/logout</code>。</p><p>其他供应商（Anthropic / OpenAI / Google 等）要<strong>直接编辑</strong> <code>~/.kimi-code/config.toml</code>，见 <a href="https://moonshotai.github.io/kimi-code/zh/configuration/providers.md" target="_blank" rel="noreferrer">平台与模型</a>。</p><blockquote><p><strong><code>export KIMI_API_KEY=…</code> 不会生效。</strong> <a href="https://moonshotai.github.io/kimi-code/zh/configuration/env-vars" target="_blank" rel="noreferrer">环境变量</a> 原文：<code>KIMI_API_KEY</code>、<code>ANTHROPIC_API_KEY</code>、<code>OPENAI_API_KEY</code> <strong>不会</strong>从 shell 自动读取，必须写进 <code>config.toml</code> 的 <code>[providers.&lt;name&gt;]</code> 或 <code>[providers.&lt;name&gt;.env]</code>。例外是 <code>KIMI_MODEL_*</code> 临时通道。</p></blockquote><h2 id="_3-第一次对话" tabindex="-1">3. 第一次对话 <a class="header-anchor" href="#_3-第一次对话" aria-label="Permalink to &quot;3. 第一次对话&quot;">​</a></h2><p>官方建议先让它摸清仓库：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看一下这个项目的目录结构，简单介绍一下每个目录是做什么的</span></span></code></pre></div><p>只读工具默认自动跑。改文件或跑 Shell <strong>默认先问你</strong>。</p><p>再试一个具体任务（官方原文示例）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在 src/utils 里新增一个函数，用来把任意字符串转成 kebab-case，并补一个单元测试</span></span></code></pre></div><p>项目规则：在仓库里跑 <code>/init</code>，生成 <code>AGENTS.md</code>（帮助中心：<a href="https://www.kimi.ai/zh-hans/help/kimi-code/cli-getting-started" target="_blank" rel="noreferrer">cli-getting-started</a>）。</p><p>单次、不进 TUI：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;帮我看一下这个项目的目录结构&quot;</span></span></code></pre></div><p>继续<strong>当前目录最近一次</strong>会话：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kimi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span></span></code></pre></div><p>这是 <code>--continue</code> 的短选项，来自 <a href="https://moonshotai.github.io/kimi-code/zh/reference/kimi-command" target="_blank" rel="noreferrer">kimi 命令</a> 和 Getting Started。帮助中心有的页面写成 <code>-C</code>，以 CLI 参考为准。</p><p>退出 TUI：<code>/exit</code>，或空闲时连按两次 <code>Ctrl-C</code>，或输入框为空时 <code>Ctrl-D</code>。</p><h2 id="_4-交互、审批与三种权限模式" tabindex="-1">4. 交互、审批与三种权限模式 <a class="header-anchor" href="#_4-交互、审批与三种权限模式" aria-label="Permalink to &quot;4. 交互、审批与三种权限模式&quot;">​</a></h2><p>来源：<a href="https://moonshotai.github.io/kimi-code/zh/guides/interaction" target="_blank" rel="noreferrer">交互与输入</a>。</p><table tabindex="0"><thead><tr><th>操作</th><th>做法</th></tr></thead><tbody><tr><td>发送</td><td><code>Enter</code></td></tr><tr><td>换行</td><td><code>Shift-Enter</code> 或 <code>Ctrl-J</code></td></tr><tr><td>引用文件</td><td><code>@</code> 路径补全</td></tr><tr><td>斜杠命令</td><td><code>/</code></td></tr><tr><td>粘贴图片 / 视频</td><td>macOS / Linux <code>Ctrl-V</code>；Windows <code>Alt-V</code></td></tr><tr><td>流式中插话</td><td><code>Ctrl-S</code></td></tr><tr><td>中断</td><td><code>Esc</code> 或 <code>Ctrl-C</code></td></tr><tr><td>折叠工具输出</td><td><code>Ctrl-O</code></td></tr><tr><td>外部编辑器</td><td><code>Ctrl-G</code></td></tr><tr><td>切 Plan</td><td><code>Shift-Tab</code> 或 <code>/plan</code></td></tr><tr><td>进 Shell 模式</td><td>空输入框键入 <code>!</code></td></tr></tbody></table><p>三种模式不要混：</p><table tabindex="0"><thead><tr><th>模式</th><th>怎么开</th><th>官方行为</th></tr></thead><tbody><tr><td><strong>Plan</strong></td><td><code>Shift-Tab</code> / <code>/plan</code> / <code>kimi --plan</code></td><td>先出方案，你批准才改文件。退出 Plan 仍要确认；<strong>YOLO 也跳不过</strong></td></tr><tr><td><strong>YOLO</strong></td><td><code>/yolo</code> / <code>kimi --yolo</code></td><td>自动批准普通工具（含写文件、Shell）。敏感文件（如 <code>.env</code>、SSH 私钥）和退出 Plan 仍会问</td></tr><tr><td><strong>Auto</strong></td><td><code>/auto</code> / <code>kimi --auto</code></td><td>所有审批自动处理，<strong>Agent 不再向你提问</strong></td></tr></tbody></table><p><code>-p</code> 非交互固定走 <code>auto</code> 权限，不能和 <code>--yolo</code> / <code>--auto</code> / <code>--plan</code> 一起用。</p><h2 id="_5-常用斜杠命令" tabindex="-1">5. 常用斜杠命令 <a class="header-anchor" href="#_5-常用斜杠命令" aria-label="Permalink to &quot;5. 常用斜杠命令&quot;">​</a></h2><p>入门够用的一组，来自 Getting Started。全集在 <a href="https://moonshotai.github.io/kimi-code/zh/reference/slash-commands" target="_blank" rel="noreferrer">斜杠命令</a> 和 <a href="./kimi-code-cheatsheet.html">速查表</a>。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>命令与快捷键面板</td></tr><tr><td><code>/login</code> / <code>/logout</code></td><td>登录 / 清凭证</td></tr><tr><td><code>/model</code></td><td>切换模型</td></tr><tr><td><code>/new</code></td><td>新会话</td></tr><tr><td><code>/sessions</code></td><td>恢复历史会话</td></tr><tr><td><code>/compact</code></td><td>压缩上下文</td></tr><tr><td><code>/fork</code></td><td>派生一份独立副本（你仍留在当前会话）</td></tr><tr><td><code>/init</code></td><td>生成 <code>AGENTS.md</code></td></tr><tr><td><code>/usage</code></td><td>用量与配额</td></tr><tr><td><code>/yolo</code> <code>/auto</code> <code>/plan</code></td><td>权限 / 计划模式</td></tr><tr><td><code>/goal</code></td><td>跨轮次推进一个持久目标</td></tr><tr><td><code>/mcp-config</code></td><td>对话式配置 MCP</td></tr></tbody></table><h2 id="_6-kimi-code-for-vs-code" tabindex="-1">6. Kimi Code for VS Code <a class="header-anchor" href="#_6-kimi-code-for-vs-code" aria-label="Permalink to &quot;6. Kimi Code for VS Code&quot;">​</a></h2><p>官方页：<a href="https://www.kimi.com/code/docs/kimi-code-for-vscode/getting-started" target="_blank" rel="noreferrer">快速开始</a>。扩展市场：<a href="https://marketplace.visualstudio.com/items?itemName=moonshot-ai.kimi-code" target="_blank" rel="noreferrer">moonshot-ai.kimi-code</a>。</p><h3 id="先读这句资格声明" tabindex="-1">先读这句资格声明 <a class="header-anchor" href="#先读这句资格声明" aria-label="Permalink to &quot;先读这句资格声明&quot;">​</a></h3><p>产品文档横幅原文：</p><blockquote><p>Kimi Code for VS Code 目前仅对旧版 Python CLI 用户开放新增安装。已安装插件的老用户升级新版 CLI 后仍可继续使用，其他 TS 版本 CLI 用户暂不支持安装。</p></blockquote><p>帮助中心同一句话。<strong>新装了现行 Node CLI 的人，不要默认扩展市场一点就能用。</strong> 编辑器需求优先走下面的 <code>kimi acp</code>，或在 VS Code 集成终端里跑 <code>kimi</code>。</p><p>Marketplace 页（2026-08-19 看到 0.7.0）另有一套更新的实现说明，和上面横幅<strong>同时存在</strong>：</p><ul><li>需要 VS Code <strong>1.100.0</strong> 或更高</li><li>扩展在 Extension Host 里跑 <strong>Kimi Code Node SDK</strong></li><li>与终端 App 解析到同一 <code>KIMI_CODE_HOME</code> 时，共享 <code>config.toml</code>、MCP、登录态和会话</li><li><strong>不要</strong>同时在扩展和终端打开同一个 session（跨进程锁不保证）</li></ul><p>两份官方页打架时，<strong>安装资格跟产品文档横幅</strong>；共享 home / 版本要求跟 Marketplace。不要猜哪边已经作废。</p><h3 id="安装与登录-官方步骤" tabindex="-1">安装与登录（官方步骤） <a class="header-anchor" href="#安装与登录-官方步骤" aria-label="Permalink to &quot;安装与登录（官方步骤）&quot;">​</a></h3><ol><li>前提：Kimi 账号订阅或 API Key</li><li>在 VS Code Marketplace 搜 <strong>Kimi Code</strong>，认准发布者 <strong>moonshot-ai</strong></li><li>看不到扩展：重启，或命令面板执行 <code>Developer: Reload Window</code>（macOS <code>Cmd+Shift+P</code>，Windows/Linux <code>Ctrl+Shift+P</code>）</li><li>点活动栏 Kimi 图标</li><li>认证（齿轮可切换）： <ul><li><strong>Kimi 账号模式</strong>：浏览器授权</li><li><strong>API Key 模式</strong>：已有 Key 可跳过登录</li></ul></li></ol><h3 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h3><p>官方四个配方：</p><table tabindex="0"><thead><tr><th>场景</th><th>做法</th></tr></thead><tbody><tr><td>代码解读</td><td><code>@</code> 选文件 / 文件夹，问流程，再追问</td></tr><tr><td>重构</td><td>如 <code>@src/feature/</code>，看 diff，选择性批准，必要时回退</td></tr><tr><td>调试</td><td>粘贴报错或堆栈，引用相关文件，批准修复</td></tr><tr><td>项目概览</td><td>如 <code>@src/services/</code>，要模块图或架构摘要</td></tr></tbody></table><h3 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h3><p>来自产品文档（比帮助中心多一条设置说明）：</p><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl+Shift+K</code> / <code>Cmd+Shift+K</code></td><td>聚焦 Kimi 输入框</td></tr><tr><td><code>Alt+K</code></td><td>插入当前文件引用</td></tr><tr><td><code>Ctrl+N</code> / <code>Cmd+N</code></td><td>新建对话（需打开 <code>kimi.enableNewConversationShortcut</code>；占用系统默认「新建文件」）</td></tr><tr><td><code>↑</code> / <code>↓</code></td><td>浏览输入历史</td></tr></tbody></table><p>命令面板搜 <code>Kimi Code</code> 可在新标签页 / 侧边栏打开、管理会话。</p><h2 id="_7-在其他-ide-里用-acp" tabindex="-1">7. 在其他 IDE 里用 ACP <a class="header-anchor" href="#_7-在其他-ide-里用-acp" aria-label="Permalink to &quot;7. 在其他 IDE 里用 ACP&quot;">​</a></h2><p>官方没有第一方 JetBrains / Zed 插件。CLI 暴露 <code>kimi acp</code>，IDE 用子进程 + JSON-RPC。先在终端完成 <code>/login</code>。macOS 从 GUI 拉起的子进程常常<strong>没有</strong>你的 shell <code>PATH</code>，<code>command</code> 要用 <code>which kimi</code> 的绝对路径。</p><p>Zed，写入 <code>~/.config/zed/settings.json</code>（<a href="https://moonshotai.github.io/kimi-code/zh/guides/ides" target="_blank" rel="noreferrer">在 IDE 中使用</a>）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;Kimi Code CLI&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;kimi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>JetBrains（IntelliJ / PyCharm / WebStorm 等）在 AI 聊天里配 ACP，<code>command</code> <strong>必须绝对路径</strong>。Paseo 选内置 provider 或在 <code>~/.paseo/config.json</code> 写 <code>[&quot;kimi&quot;, &quot;acp&quot;]</code>。</p><p>自检：终端跑 <code>kimi acp</code>。若阻塞等 stdin，CLI 正常，问题在 IDE 配置；立刻报错多半是没登录。</p><h2 id="_8-把-kimi-code-接到第三方工具" tabindex="-1">8. 把 Kimi Code 接到第三方工具 <a class="header-anchor" href="#_8-把-kimi-code-接到第三方工具" aria-label="Permalink to &quot;8. 把 Kimi Code 接到第三方工具&quot;">​</a></h2><p>产品总览：会员可在 <a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">控制台</a> 建最多 <strong>5</strong> 个 API Key（<strong>只在创建时显示一次</strong>）。</p><table tabindex="0"><thead><tr><th>协议</th><th>Base URL</th><th>常用 Endpoint</th></tr></thead><tbody><tr><td>OpenAI 兼容</td><td><code>https://api.kimi.com/coding/v1</code></td><td><code>https://api.kimi.com/coding/v1/chat/completions</code></td></tr><tr><td>Anthropic 兼容</td><td><code>https://api.kimi.com/coding/</code></td><td><code>https://api.kimi.com/coding/v1/messages</code></td></tr></tbody></table><p>有的工具只要 Base URL（如 Claude Code），有的要完整 Endpoint（总览举例 Trae）。</p><p>官方点名的接入面：Claude Code、OpenCode、Codex、Roo Code，以及 OpenClaw、Hermes 等通用框架（<a href="https://www.kimi.com/zh-cn/help/kimi-code/membership-guide" target="_blank" rel="noreferrer">membership-guide</a>）。逐步配置跟各工具自己的文档，本页不编环境变量名。</p><blockquote><p>总览原文：「使用时请保持工具的真实身份标识，篡改客户端标识（User-Agent）将被视为违规，可能导致会员权益暂停。」</p></blockquote><p>这和开放平台不是一回事：</p><table tabindex="0"><thead><tr><th></th><th>Kimi Code 平台</th><th>Kimi 开放平台</th></tr></thead><tbody><tr><td>Base URL</td><td>上表</td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>计费</td><td>会员订阅，有频控</td><td>按量充值</td></tr><tr><td>场景</td><td>终端 / IDE Agent</td><td>产品集成、企业调用</td></tr></tbody></table><p>Key <strong>不能</strong>混用。</p><h2 id="_9-模型怎么选" tabindex="-1">9. 模型怎么选 <a class="header-anchor" href="#_9-模型怎么选" aria-label="Permalink to &quot;9. 模型怎么选&quot;">​</a></h2><p>以 2026-08-19 的 <a href="https://www.kimi.com/code/docs/kimi-code/models" target="_blank" rel="noreferrer">模型配置</a> 为准。该页写「共 <strong>3</strong> 个模型 ID」。</p><table tabindex="0"><thead><tr><th>Model ID</th><th>对应模型</th><th>上下文</th><th>谁能用</th></tr></thead><tbody><tr><td><code>k3</code></td><td>Kimi K3</td><td>Moderato 最高 256k；Allegretto 及以上最高 1M</td><td>Moderato 及以上。Andante：暂不支持</td></tr><tr><td><code>kimi-for-coding</code></td><td>Kimi K2.7 Code</td><td>256k</td><td>所有会员</td></tr><tr><td><code>kimi-for-coding-highspeed</code></td><td>同一 K2.7 Code 的高速版</td><td>256k</td><td>Allegretto 及以上</td></tr></tbody></table><p>官方：高速版编码能力与标准版一致；产品文档写输出约 <strong>5–6 倍</strong>、额度约 <strong>3 倍</strong>；models 页表格写「6 倍速 3 倍消耗」。填错高速版 ID <strong>不报错</strong>，会兜底到 <code>kimi-for-coding</code>。权限不够返回 <strong>401</strong>。</p><p>CLI 里 <code>/model</code> 切换。VS Code 在输入栏下拉选；没有目标模型就重启或重装扩展。切模型会使缓存失效，官方建议<strong>新开 session</strong>。</p><h2 id="_10-数据在哪、额度怎么查" tabindex="-1">10. 数据在哪、额度怎么查 <a class="header-anchor" href="#_10-数据在哪、额度怎么查" aria-label="Permalink to &quot;10. 数据在哪、额度怎么查&quot;">​</a></h2><ul><li>默认数据根：<code>~/.kimi-code/</code>（配置、会话、日志、更新缓存）</li><li>搬家：环境变量 <code>KIMI_CODE_HOME</code></li><li>不要手改 <code>sessions/</code> 下的文件</li><li>查用量：TUI <code>/usage</code>；网页 <strong>设置 → 订阅和发票 → 我的额度</strong>；控制台在开启加油包后也可看</li></ul><p>额度规则只抄 <a href="https://www.kimi.com/code/docs/kimi-code/membership" target="_blank" rel="noreferrer">会员权益</a>：7 天刷新、5 小时滚动窗口、设备 / API Key 共享配额、30 天不活跃设备解绑、月额度打满会冻 Code。新会员体系即将把 Code 与 Kimi 会员拆开——档位数字去官方会员页，这里不写死。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ol><li><strong>抄了旧安装 URL 或旧包名。</strong> 现行是 <code>code.kimi.com/kimi-code/install.sh</code> 和 <code>@moonshot-ai/kimi-code</code>。</li><li><strong><code>export KIMI_API_KEY</code> 当登录。</strong> 必须写进 <code>config.toml</code> 或走 <code>/login</code>。</li><li><strong>Coding Key 拿去打 <code>api.moonshot.cn</code>，或反过来。</strong> 两套账号。</li><li><strong>YOLO 和 Auto 当成一回事。</strong> Auto 连提问都关；YOLO 仍会问敏感文件和退出 Plan。</li><li><strong>新 Node CLI 用户默认 VS Code 扩展可用。</strong> 产品文档说新装只对旧 Python CLI 用户开放。</li><li><strong>IDE 里 <code>kimi: command not found</code>。</strong> GUI 子进程没有 PATH，填绝对路径。</li><li><strong>Windows 没装 Git for Windows。</strong> 官方要求用 Git Bash；What&#39;s New：缺 Git Bash 时启动前就会报错。</li><li><strong>继续会话写成帮助中心的 <code>-C</code>。</strong> CLI 参考是 <code>-c</code> / <code>--continue</code>。</li></ol><h2 id="附录-从-python-kimi-cli-迁移" tabindex="-1">附录：从 Python kimi-cli 迁移 <a class="header-anchor" href="#附录-从-python-kimi-cli-迁移" aria-label="Permalink to &quot;附录：从 Python kimi-cli 迁移&quot;">​</a></h2><p>旧版将不再维护。不要把它当主 Tutorial。</p><p><a href="https://www.kimi.com/code/docs/kimi-code/whats-new" target="_blank" rel="noreferrer">What&#39;s New</a> 对照：</p><table tabindex="0"><thead><tr><th>对比项</th><th>旧版 kimi-cli</th><th>新版 Kimi Code CLI</th></tr></thead><tbody><tr><td>运行时</td><td>Python + uv</td><td>Node.js</td></tr><tr><td>安装</td><td><code>uv tool install</code></td><td>本页第 1 节的 curl / npm</td></tr><tr><td>配置</td><td><code>~/.kimi/config.toml</code></td><td><code>~/.kimi-code/config.toml</code>（<strong>格式不兼容</strong>）</td></tr><tr><td>界面</td><td>基础文本</td><td>全功能 TUI</td></tr><tr><td>子 Agent</td><td>不支持</td><td>内置 <code>coder</code> / <code>explore</code> / <code>plan</code></td></tr></tbody></table><p><a href="https://www.kimi.com/code/docs/kimi-code-cli/guides/migration" target="_blank" rel="noreferrer">迁移指南</a>：</p><ol><li>按本页装好新版。</li><li>第一次跑 <code>kimi</code> 时，若检测到 <code>~/.kimi/</code>，会弹出迁移提示。</li><li>随时可手动：<code>kimi migrate</code>。</li><li>可选 <strong>Config only</strong> 或 <strong>Config + N sessions</strong>。</li></ol><p>会迁移：<code>config.toml</code>、MCP 配置、输入历史、你勾选的会话。</p><p><strong>不会</strong>迁移：OAuth 凭证、MCP 授权、旧版插件。迁完重新 <code>/login</code> 并重授 MCP。</p><p>迁移<strong>不删</strong> <code>~/.kimi/</code>。可重复跑，已导入会话带 <code>[imported]</code>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>参数、模型、Base URL → <a href="./kimi-code-cheatsheet.html">速查表</a></li><li>官方场景配方 → <a href="https://moonshotai.github.io/kimi-code/zh/guides/use-cases" target="_blank" rel="noreferrer">常见使用案例</a></li><li>Skills / MCP / Hooks → <a href="https://moonshotai.github.io/kimi-code/zh/customization/mcp" target="_blank" rel="noreferrer">定制化</a></li><li>问题反馈 → <a href="https://github.com/MoonshotAI/kimi-code/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li></ul>`,108)])])}const u=e(a,[["render",s]]);export{b as __pageData,u as default};
